import{_ as t,o,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Follow the Advice, but Not Too Closely - Building the Cluster YOU Need - Gregory Orange, Pawsey","description":"","frontmatter":{"title":"Follow the Advice, but Not Too Closely - Building the Cluster YOU Need - Gregory Orange, Pawsey","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph集群设计","分布式存储","Ceph运维","Ceph-Ansible","Ceph社区"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Follow_the_Advice_but_Not_Too_Closely_-_Building_the_Cluster_YOU_Need_-_Gregory_Orange_Pawsey.md","filePath":"posts/2025/Follow_the_Advice_but_Not_Too_Closely_-_Building_the_Cluster_YOU_Need_-_Gregory_Orange_Pawsey.md","lastUpdated":1780459816000}'),a={name:"posts/2025/Follow_the_Advice_but_Not_Too_Closely_-_Building_the_Cluster_YOU_Need_-_Gregory_Orange_Pawsey.md"};function s(n,e,i,_,h,g){return o(),r("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>: Ceph集群设计与部署经验分享<br><strong>主讲人</strong>: Greg (来自Pawsey超级计算研究中心)<br><strong>会议时间</strong>: 不详<br><strong>会议地点</strong>: 不详</p><h4 id="_1-会议背景与目标" tabindex="-1">1. <strong>会议背景与目标</strong> <a class="header-anchor" href="#_1-会议背景与目标" aria-label="Permalink to &quot;1. **会议背景与目标**&quot;">​</a></h4><ul><li>Greg介绍了Pawsey超级计算研究中心的工作，主要提供高性能计算、数据云和可视化服务，支持广泛的科学研究领域。</li><li>本次会议重点讨论了如何设计和部署一个新的20 PB Ceph集群，以实现高可用性、高性能和成本效益，同时遵循社区的推荐。</li></ul><h4 id="_2-ceph集群设计的关键考虑因素" tabindex="-1">2. <strong>Ceph集群设计的关键考虑因素</strong> <a class="header-anchor" href="#_2-ceph集群设计的关键考虑因素" aria-label="Permalink to &quot;2. **Ceph集群设计的关键考虑因素**&quot;">​</a></h4><ul><li><strong>硬件规格</strong>: 集群主要由60个22 TB硬盘组成的JBOD存储单元构成，每个存储单元连接到一个头节点。</li><li><strong>CPU配置</strong>: 考虑到OSD节点的CPU使用率较低，团队在新集群中减少了CPU的配置，每个存储单元配置64核CPU。</li><li><strong>网络配置</strong>: 使用400 Gbit的网络主干，并通过100 Gbit链路连接所有新设备，采用Broadcom NIC以降低成本。</li><li><strong>节点冗余</strong>: 集群仅使用24个存储单元，保留2个备用，以应对节点故障导致的长时间重建。</li></ul><h4 id="_3-ceph集群的管理与部署" tabindex="-1">3. <strong>Ceph集群的管理与部署</strong> <a class="header-anchor" href="#_3-ceph集群的管理与部署" aria-label="Permalink to &quot;3. **Ceph集群的管理与部署**&quot;">​</a></h4><ul><li><strong>从Ceph Volume迁移到Ceph-Ansible</strong>: 团队正在从使用Ceph Volume迁移到Ceph-Ansible，以更好地利用资源，特别是通过容器化技术。</li><li><strong>索引节点</strong>: 由于集群用于RADOS Gateway (RGW)，需要高性能的索引池，尽管索引池的规模较小，但仍配置了四个索引节点。</li></ul><h4 id="_4-设计集群的挑战与建议" tabindex="-1">4. <strong>设计集群的挑战与建议</strong> <a class="header-anchor" href="#_4-设计集群的挑战与建议" aria-label="Permalink to &quot;4. **设计集群的挑战与建议**&quot;">​</a></h4><ul><li><strong>明确需求</strong>: 设计集群时，必须明确用户的需求，包括性能、容量和可用性要求。</li><li><strong>成本与性能的平衡</strong>: Ceph可以提供高吞吐量和低成本，但不能在所有场景下都做到完美。</li><li><strong>用户需求与预算</strong>: 设计时需要考虑预算、现有设备和用户的性能需求。</li></ul><h4 id="_5-ceph的操作模式" tabindex="-1">5. <strong>Ceph的操作模式</strong> <a class="header-anchor" href="#_5-ceph的操作模式" aria-label="Permalink to &quot;5. **Ceph的操作模式**&quot;">​</a></h4><ul><li><strong>自运营模式</strong>: 完全自行管理Ceph集群，深入了解部署和运维的各个方面。</li><li><strong>支持模式</strong>: 自行管理集群，但购买部分支持服务。</li><li><strong>托管模式</strong>: 使用完全托管的Ceph解决方案。</li><li><strong>SaaS模式</strong>: 将Ceph作为软件即服务（SaaS）运行在公有云上。</li></ul><h4 id="_6-自动化与文档管理" tabindex="-1">6. <strong>自动化与文档管理</strong> <a class="header-anchor" href="#_6-自动化与文档管理" aria-label="Permalink to &quot;6. **自动化与文档管理**&quot;">​</a></h4><ul><li><strong>自动化</strong>: 从手动操作到脚本自动化，再到使用更复杂的自动化工具，逐步提升集群管理的效率。</li><li><strong>文档与维护</strong>: 保持良好的文档和代码维护，特别是在团队成员变动时，确保新成员能够快速上手。</li></ul><h4 id="_7-故障处理与集群设计" tabindex="-1">7. <strong>故障处理与集群设计</strong> <a class="header-anchor" href="#_7-故障处理与集群设计" aria-label="Permalink to &quot;7. **故障处理与集群设计**&quot;">​</a></h4><ul><li><strong>故障模拟</strong>: 通过测试集群模拟各种故障场景，如设备故障、配置错误等。</li><li><strong>多集群管理</strong>: 运行多个Ceph集群可以提高系统的可用性和可维护性。</li></ul><h4 id="_8-总结与建议" tabindex="-1">8. <strong>总结与建议</strong> <a class="header-anchor" href="#_8-总结与建议" aria-label="Permalink to &quot;8. **总结与建议**&quot;">​</a></h4><ul><li><strong>灵活性与成本效益</strong>: 大型的HDD集群在满足用户需求和有适当支持的情况下，可以实现高效且经济的存储解决方案。</li><li><strong>社区支持</strong>: 无论选择哪种操作模式，社区的支持和知识分享都是宝贵的资源。</li></ul><p><strong>后续行动计划</strong>:</p><ol><li>继续优化Ceph-Ansible的部署和自动化脚本。</li><li>进行更多的故障模拟测试，确保集群在实际运行中的稳定性。</li><li>与社区和其他Ceph用户保持紧密联系，分享经验并获取支持。</li></ol>',20)])])}const p=t(a,[["render",s]]);export{u as __pageData,p as default};
